@Composable
fun Counter() {
  var count by remember { mutableIntStateOf(0) }
  Column {
    // Only Text reads `count`, so only Text recomposes when it changes.
    Text("Count: \$count")
    Button(onClick = { count++ }) { Text("Increment") }
    HelloHeader()      // never reads count → never recomposes
  }
}

@Composable
fun HelloHeader() = Text("Hello!")

// Side effect — restarts when the key changes
@Composable
fun GreetingFor(userId: String) {
  var name by remember { mutableStateOf("") }
  LaunchedEffect(userId) {
    name = api.fetchName(userId)
  }
  Text("Hi, \$name")
}

