@Serializable data object Home
@Serializable data object Settings
@Serializable data class Profile(val id: Long)

@Composable
fun AppNav() {
  val navController = rememberNavController()
  NavHost(navController, startDestination = Home) {
    composable<Home> {
      HomeScreen(
        onProfile = { id -> navController.navigate(Profile(id)) },
        onSettings = { navController.navigate(Settings) }
      )
    }
    composable<Profile> { entry ->
      val args = entry.toRoute<Profile>()
      // hiltViewModel() here is scoped to THIS back-stack entry
      ProfileScreen(id = args.id, onBack = { navController.popBackStack() })
    }
    composable<Settings> { SettingsScreen() }
  }
}

// Clearing the stack, e.g. after sign-out
navController.navigate(Home) {
  popUpTo<Login> { inclusive = true }
  launchSingleTop = true
}

